onClick:
() => {
              // Open the Settings dropdown at the Auto GUI Preview toggle (the
              // setting that controls this popup), then dismiss the toast.
              useProjectStore.getState().requestOpenSettings();
              setPreviewToast(null);
            }

() => {
              const tree = trees.find((t) => t.id === activeTreeId);
              const count = store.nodes.filter(
                (n) => (n.data as any)?.treeId === activeTreeId && n.type !== 'master',
              ).length;
              if (
                confirm(
                  `Delete the app tree "${tree?.name || activeTreeId}" and its ${count} node(s)?\n\n` +
                  'Cross-tree connections wired to it are removed too.',
                )
              ) {
                removeTree(activeTreeId);
              }
            }

onChange:
e => {
                  setSourceId(e.target.value);
                  if (e.target.value === targetId) setTargetId('');
                  setResult(null); setApplied(false);
                }

onClick:
() => {
                  // Copy path to clipboard
                  navigator.clipboard.writeText(outputPath).catch(() => {});
                  addLog('📋 Path copied to clipboard!');
                }

() => {
            setSearch('');
            setExpandedSection(null);
            const allIds = HELP_SECTIONS.map(s => s.id);
            // Expand first 3 sections
            allIds.slice(0, 3).forEach(id => toggleSection(id));
          }

onChange:
(e) => {
                      const key = e.target.value;
                      setRoleDraft((d) => {
                        if (!key) {
                          const { [role]: _drop, ...rest } = d;
                          return rest;
                        }
                        const bp = backendProviders.find((p) => p.key === key);
                        if (bp) {
                          return { ...d, [role]: { baseUrl: bp.baseUrl.replace(/\/v1$/, ''), model: bp.model || currentModel || '' } };
                        }
                        const fp = PROVIDERS.find((p) => p.id === key);
                        if (fp) {
                          return { ...d, [role]: { baseUrl: fp.baseUrl, model: currentModel || '' } };
                        }
                        return d;
                      });
                      setRolesSaved(false);
                    }

(e) => {
                        const v = e.target.value;
                        setRoleDraft((d) => {
                          const cur = d[role];
                          if (cur && typeof cur !== 'string' && 'baseUrl' in cur) {
                            return { ...d, [role]: { ...cur, model: v } };
                          }
                          const bp = backendProviders.find((p) => p.key === providerKey);
                          const base = bp?.baseUrl.replace(/\/v1$/, '') || (typeof cur === 'string' ? (backendProviders.find((p) => p.key === cur)?.baseUrl || '') : '');
                          return base ? { ...d, [role]: { baseUrl: base, model: v } } : d;
                        });
                        setRolesSaved(false);
                      }

(e) => {
                        const v = e.target.value;
                        setRoleDraft((d) => {
                          const cur = d[role];
                          if (cur && typeof cur !== 'string' && 'baseUrl' in cur) {
                            return { ...d, [role]: { ...cur, apiKey: v } };
                          }
                          return d;
                        });
                        setRolesSaved(false);
                      }

onClick:
() => {
                        setRevealedKeys((prev) => {
                          const next = new Set(prev);
                          if (next.has(role)) next.delete(role); else next.add(role);
                          return next;
                        });
                      }

async () => {
              const ok = await saveRoles(roleDraft);
              if (ok) {
                setRolesSaved(true);
                setTimeout(() => setRolesSaved(false), 4000);
              }
            }

() => {
                  setShowFullApp(!showFullApp);
                  // Auto-select first file when switching to per-file mode
                  if (showFullApp && !selectedFile && generatedFiles.length > 0) {
                    setSelectedFile(generatedFiles[0].fileName);
                  }
                }

async () => {
              setBackendStatus('checking');
              const ok = await checkBackendConnection();
              setBackendStatus(ok ? 'online' : 'offline');
            }

onChange:
e => {
                const os = e.target.value as OSType;
                updateNode(id, { selectedOS: os, selectedDistro: os === 'linux' ? data.selectedDistro || 'ubuntu' : undefined });
                setTargetOS(os);
              }

e => {
                    const distro = e.target.value as LinuxDistro | '';
                    updateNode(id, { selectedDistro: distro || undefined });
                  }

onClick:
() => {
                setBuilding(true);
                setWizardStep('building-nodes');
                handleBuildFallback(userGoal, userPurpose, data.selectedOS || 'linux', data.scale || 'medium');
              }

() => {
              localStorage.removeItem(REASONING_STORAGE_KEY);
              setMessages([createInitialMsg()]);
              pendingPlanRef.current = null;
              setPendingQuestions(null);
              setPendingIntent(null);
              setIntentDraft(null);
              setCustomAnswerKeys({});
            }

() => {
          stopSpeaking();
          setSpeakingId(null);
          assistantSpeakingRef.current = false;
          assistantStateRef.current = 'idle';
          setAssistantState('idle');
          if (assistantEnabled) startAssistantCycle();
        }
